import{c as o,Z as e,Q as i,j as l,m as r,o as n}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"出塞","description":"","frontmatter":{"title":"出塞","author":"王昌龄","dynasty":"唐"},"headers":[],"relativePath":"books/shici/tangshi/10.md","filePath":"books/shici/tangshi/10.md"}'),s={name:"books/shici/tangshi/10.md"};function h(u,a,c,p,d,q){const t=e("PoemNav");return i(),l("div",null,[a[0]||(a[0]=r('<h1 id="出塞" tabindex="-1">出塞 <a class="header-anchor" href="#出塞" aria-label="Permalink to &quot;出塞&quot;">​</a></h1><p><strong>[唐] <a href="/authors/wangchangling.html">王昌龄</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>秦时明月汉时关，万里长征人未还。 但使龙城飞将在，不教胡马度阴山。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>出塞：出关塞，指到边疆戍守</li><li>秦时明月汉时关：秦汉时的明月和关隘，指代自古以来边塞的景物</li><li>万里长征：长途跋涉到边疆征战</li><li>人未还：出征的人还没有回来</li><li>但使：只要</li><li>龙城飞将：指汉代名将李广，匈奴称他为&quot;飞将军&quot;</li><li>不教：不让</li><li>胡马：指匈奴的战马，代指匈奴军队</li><li>阴山：在今内蒙古自治区，是古代中原王朝与匈奴的界山</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>秦汉时的明月照耀着秦汉时的关隘，万里长征的将士们至今还没有归来。只要有像李广那样的飞将军在，就不会让匈奴的战马越过阴山。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首诗是王昌龄的边塞诗代表作，表达了对边疆将士的同情和对良将的渴望，被誉为唐人七绝的压卷之作。</p><p>首句&quot;秦时明月汉时关&quot;，运用互文手法，将秦汉连在一起，写出了边塞历史的悠久。明月和关隘都是边塞的典型意象，诗人将它们与秦汉联系起来，营造出一种雄浑苍茫的意境。</p><p>次句&quot;万里长征人未还&quot;，写边塞战争的漫长和残酷。&quot;万里&quot;极言征途之远，&quot;人未还&quot;则暗示了战争的惨烈和将士的牺牲，表达了诗人对征人的深切同情。</p><p>后两句&quot;但使龙城飞将在，不教胡马度阴山&quot;，是全诗的主旨所在。诗人借汉代名将李广的典故，表达了对良将的渴望和对和平的向往。只要有像李广那样的名将镇守边关，外敌就不敢入侵，百姓就能安居乐业。</p><p>全诗气势雄浑，意境深远，将历史的沧桑、战争的残酷和对和平的渴望融为一体，体现了盛唐边塞诗的典型风格。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>王昌龄</strong>（698年－757年），字少伯，唐代著名边塞诗人，被誉为&quot;七绝圣手&quot;。其诗以七绝见长，多写边塞军旅生活，风格雄浑豪放。</p><p><a href="/authors/wangchangling.html">查看作者详情 →</a></p></blockquote>',17)),n(t)])}const b=o(s,[["render",h]]);export{m as __pageData,b as default};
